const item = $input.item.json;
const fields = item.fields || item.body?.fields || item.body || item;

const recordId = item.id || item.body?.id || fields.id || ('rec_' + Date.now());
const title = fields.Title || fields.title || 'Untitled Post';
const keyMessage = fields.KeyMessage || fields.key_message || '';
const mediaUrls = Array.isArray(fields.MediaURLs) ? fields.MediaURLs : (fields.MediaURLs ? [fields.MediaURLs] : []);
const targetPlatforms = Array.isArray(fields.TargetPlatforms) && fields.TargetPlatforms.length > 0 
  ? fields.TargetPlatforms 
  : ['linkedin', 'x', 'instagram'];
const publishAt = fields.PublishAt || fields.publish_at || null;

if (!keyMessage) {
  throw new Error("Missing required 'KeyMessage' in calendar record.");
}

return {
  json: {
    record_id: recordId,
    title: title,
    key_message: keyMessage,
    media_urls: mediaUrls,
    target_platforms: targetPlatforms,
    publish_at: publishAt,
    attempt: 1
  }
};

const inputData = $('Extract & Validate Input').item.json;
const llmResponse = $input.item.json;

let variants = {};
try {
  const content = llmResponse.choices[0].message.content;
  variants = JSON.parse(content);
} catch (e) {
  throw new Error("Failed to parse LLM variants JSON: " + e.message);
}

const validationErrors = [];

// 1. Validate X length (strict 280 weighted characters rule)
if (variants.x) {
  // URLs consume fixed 23 chars; simple weighted approximation
  const textWithoutUrls = variants.x.replace(/https?:\/\/\S+/g, '');
  const urlCount = (variants.x.match(/https?:\/\/\S+/g) || []).length;
  const weightedLen = textWithoutUrls.length + (urlCount * 23);
  if (weightedLen > 280) {
    validationErrors.push("X post exceeds 280 weighted characters (" + weightedLen + " computed).");
  }
}

// 2. Validate Instagram media requirement & hashtags
if (variants.instagram) {
  if (!inputData.media_urls || inputData.media_urls.length === 0) {
    validationErrors.push("Instagram requires at least one image or video URL. Text-only posting is unsupported.");
  }
  const hashtagCount = (variants.instagram.match(/#[a-zA-Z0-9_]+/g) || []).length;
  if (hashtagCount > 30) {
    validationErrors.push("Instagram post exceeds 30 hashtags (" + hashtagCount + " detected).");
  }
  if (variants.instagram.length > 2200) {
    validationErrors.push("Instagram caption exceeds 2200 characters limit.");
  }
}

// 3. Validate LinkedIn length
if (variants.linkedin && variants.linkedin.length > 3000) {
  validationErrors.push("LinkedIn post exceeds 3000 characters limit.");
}

const isValid = validationErrors.length === 0;

return {
  json: {
    ...inputData,
    variants: variants,
    is_valid: isValid,
    validation_notes: validationErrors.join('; '),
    status: isValid ? 'ready_for_approval' : 'needs_edit'
  }
};
